head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

xf:group.script:

				/**
				* //property handling
				* $w.log("gridId:" + options.gridId);
				* $w.log("fromColumName:" + options.fromColumName);
				* $w.log("toColumnName:" + options.toColumnName);
				* $w.log("id:" + options.id);
				* $w.log("class:" + options.class);
				*
				* //event trigger
				*/
				var udcId 			= options.id;
				var locFectchIptObj = WebSquare.wUnit.getObjById( udcId+"_iptLocFectch" );
				var totFectchIptObj = WebSquare.wUnit.getObjById( udcId+"_iptTotFectch" );
				var locFectchBtnObj = WebSquare.wUnit.getObjById( udcId+"_btnLocFetch" );
				var totFectchBtnObj = WebSquare.wUnit.getObjById( udcId+"_btnTotalFetch" );

				//초가화
				udc_obj.initPaging = function(options){

					locFectchIptObj.setValue(0);
					totFectchIptObj.setValue(0);

					var properties 		= options;
					var adjustGrdId 	= properties.adjustGrdId;
					var totalDsId 		= properties.totalDsId;
					var fetchType 		= properties.fetchType;
					var formPageColNm 	= properties.formPageColNm;		
					var toPageColNm 	= properties.toPageColNm;
					var recCntColNm 	= properties.recCntColNm;
					var totalDsColNm 	= properties.totalDsColNm;
					udc_obj.options = properties;

					if(typeof adjustGrdId === "undefined"){
						ngmf.alert("Grid Component id는 필수속성 입니다.");
						return;
					}

					properties.reqDs 		= "";
					properties.orgTrxCode 	= "";
					properties.wfmID		= "";

					if(typeof scwin.$w !== "undefined"){
						var grids = WebSquare.wUnit.getJq("div[id$='"+adjustGrdId+"']");

						for(var i=0; i<grids.length; i++){
							var gridId = grids.get(i).id;
							var wfmId = gridId.replace("_"+adjustGrdId,"");

							if(options.id.indexOf(wfmId) > -1){
								properties.wfmID = wfmId;
								break;
							}

						}

						if(String(properties.wfmID).length > 0){
							properties.adjustGrdId 	= properties.wfmID + "_"+ adjustGrdId;
							properties.totalDsId 	= properties.wfmID + "_"+ totalDsId;
							adjustGrdId 	= properties.adjustGrdId;
							totalDsId 		= properties.totalDsId;
						}

					}

					var adjustedGrd 	= ngmf.scwin.object(adjustGrdId);
					var adjustedGrdDs 	= ngmf.scwin.object(adjustedGrd.getDataList());
					var totalDs 		= ngmf.scwin.object(totalDsId);

					//데이터로드 이벤트
					adjustedGrdDs.bind("ondataload", function(){
						locFectchIptObj.setValue(adjustedGrdDs.getRowCount());

						var totCnt = Number(totFectchIptObj.getValue());
						var locCnt = Number(locFectchIptObj.getValue()); 

						if(totCnt > 0){
							if(totCnt == locCnt){
								locFectchBtnObj.setDisabled(true);
								totFectchBtnObj.setDisabled(true);
							}else{
								locFectchBtnObj.setDisabled(false);
								totFectchBtnObj.setDisabled(false);
							}
						}			
					});

					//데이터로드 이벤트
					totalDs.bind("ondataload", function(){

						var totalCnt = 0;
						if(this.getCellData(0, totalDsColNm) != null && this.getCellData(0, totalDsColNm) != ""){
							totalCnt = this.getCellData(0, totalDsColNm);
						}

						totFectchIptObj.setValue(totalCnt);

						var totCnt = Number(totFectchIptObj.getValue());
						var locCnt = Number(locFectchIptObj.getValue()); 

						if(totCnt > 0){
							if(totCnt == locCnt){
								locFectchBtnObj.setDisabled(true);
								totFectchBtnObj.setDisabled(true);
							}else{
								locFectchBtnObj.setDisabled(false);
								totFectchBtnObj.setDisabled(false);
							}
						}else{
							locFectchBtnObj.setDisabled(true);
							totFectchBtnObj.setDisabled(true);
						}
					});

					scwin.setType(fetchType);

				};

				//조회조건 체크
				scwin.checkCondition = function(){

					var properties 		= udc_obj.options;
					var condChkFunc		= properties.conditionCheckFunction;

					if(typeof condChkFunc !== "undefined"){

						if(String(properties.wfmID).length > 0){
							var wfmId = properties.wfmID;
							condChkFunc = wfmId+"_"+condChkFunc;
						}

						return eval(condChkFunc+"()");

					}else{
						return true;
					}

				};


				//다음버튼 클릭 이벤트
				locFectchBtnObj.bind("onclick", function(e){

					var properties 		= udc_obj.options;
					var formPageColNm 	= properties.formPageColNm;
					var toPageColNm 	= properties.toPageColNm;
					var recCntColNm 	= properties.recCntColNm;
					var reqDs			= ngmf.scwin.object(String(properties.reqDs));

					var isGo = true;
					isGo = scwin.checkCondition();

					if(isGo){

						if(ngmf.makeHeadSet(properties.orgTrxCode, ngmf.getFormID()) != "OK") {

							if(GLV.G_FORMUSEFG == "M") {
								ngmf.setSystemMsg("헤더 정보를 로드하는데 실패 하였습니다.");
							}

							return;     
						}

						var p1 = reqDs.getCellData(0,formPageColNm);
						var p2 = reqDs.getCellData(0,toPageColNm);
						var p3 = reqDs.getCellData(0,recCntColNm);

						reqDs.setCellData(0,formPageColNm, Number(p1)+1);
						reqDs.setCellData(0,toPageColNm, Number(p2)+1);
						$w.executeSubmission(String(properties.orgTrxCode));
					}

				});

				//전체버튼 클릭 이벤트
				totFectchBtnObj.bind("onclick", function(e){

					var properties 		= udc_obj.options;
					var recCntColNm 	= properties.recCntColNm;
					var totalDsColNm 	= properties.totalDsColNm;
					var formPageColNm 	= properties.formPageColNm;
					var toPageColNm 	= properties.toPageColNm;
					var adjustGrdId 	= properties.adjustGrdId;
					var adjustGrd 		= ngmf.scwin.object(adjustGrdId);
					var adjustedGrdDs	= ngmf.scwin.object(adjustGrd.getDataList());
					var totalDsId 		= properties.totalDsId;
					var totalDs 		= ngmf.scwin.object(totalDsId);

					var isGo = true;
					isGo = scwin.checkCondition();

					if(isGo){

						if(ngmf.makeHeadSet(properties.orgTrxCode, ngmf.getFormID()) != "OK") {

							if(GLV.G_FORMUSEFG == "M") {
								ngmf.setSystemMsg("헤더 정보를 로드하는데 실패 하였습니다.");
							}

							return;     
						}

						var reqDs		= ngmf.scwin.object(String(properties.reqDs));
						var recCnt 		= reqDs.getCellData(0,recCntColNm);
						var totCnt 		= totalDs.getCellData(0, totalDsColNm);
						var lastPage 	= Math.ceil(totCnt/Number(recCnt));
						reqDs.setCellData(0,formPageColNm, 	1);
						reqDs.setCellData(0,toPageColNm, 	lastPage);
						adjustedGrdDs.removeAll();
						totalDs.removeAll();
						$w.executeSubmission(String(properties.orgTrxCode));
					}

				});

				udc_obj.nextCall = function(){
					locFectchBtnObj.click();
				};

				udc_obj.totalCall = function(){
					totFectchBtnObj.click();
				};

				udc_obj.setPageInit = function(){
					var properties 		= udc_obj.options;
					var adjustGrdId 	= properties.adjustGrdId;
					var adjustGrd 		= ngmf.scwin.object(adjustGrdId);
					var adjustedGrdDs	= ngmf.scwin.object(adjustGrd.getDataList());
					var totalDsId 		= properties.totalDsId;
					var totalDs 		= ngmf.scwin.object(totalDsId);

					adjustedGrdDs.setJSON([]);
					adjustedGrdDs.removeAll();

					totalDs.setJSON([]);
					totalDs.removeAll();
				};

				udc_obj.asyncCallPromise = function(){

					var pJSON = {};

					if(arguments.length >= 1){
						pJSON.orgTrxCode 	= arguments[0];		
						pJSON.trxCode 		= arguments[0];				
					}

					if(arguments.length >= 2)	pJSON.screenName 	= arguments[1];	
					if(arguments.length >= 3)	pJSON.arg 			= arguments[2];	
					if(arguments.length >= 4)	pJSON.inData 		= arguments[3];	
					if(arguments.length >= 5)	pJSON.outData 		= arguments[4];
					if(arguments.length >= 6)	var callBackFunc 	= arguments[5];

					if(arguments.length >= 7)	pJSON.ngmv_MsgFg 	= arguments[6];	
					if(arguments.length >= 8)	pJSON.ngmv_ErrProc 	= arguments[7];		
					if(arguments.length >= 9)	pJSON.encflag		= arguments[8];		
					if(arguments.length >= 10)	pJSON.inPutStr		= arguments[9];
					if(arguments.length >= 11)	pJSON.outPutStr		= arguments[10];

					locFectchBtnObj.setDisabled(false);
					totFectchBtnObj.setDisabled(false);

					var thisObj			= ngmf.scwin.object(this.id);
					var properties 		= thisObj.options;
					var adjustGrdId 	= properties.adjustGrdId;
					var totalDsId 		= properties.totalDsId;
					var totalDs 		= ngmf.scwin.object(totalDsId);
					var splitArr		= pJSON.screenName;
					var adjustGrd		= ngmf.scwin.object(adjustGrdId);
					var adjustGrdDs		= ngmf.scwin.object(adjustGrd.getDataList());

					adjustGrdDs.removeAll();
					totalDs.removeAll();
					var syncType = "asynchronous";

					properties.orgTrxCode = pJSON.orgTrxCode;

					return new Promise(function(resolve, reject) {
						scwin.transaction(syncType, thisObj.id, pJSON, callBackFunc, resolve);
					});
				};

				udc_obj.asyncCall = function(){

					var pJSON = {};

					if(arguments.length >= 1){
						pJSON.orgTrxCode 	= arguments[0];		
						pJSON.trxCode 		= arguments[0];				
					}

					if(arguments.length >= 2)	pJSON.screenName 	= arguments[1];	
					if(arguments.length >= 3)	pJSON.arg 			= arguments[2];	
					if(arguments.length >= 4)	pJSON.inData 		= arguments[3];	
					if(arguments.length >= 5)	pJSON.outData 		= arguments[4];
					//if(arguments.length >= 6)	pJSON.callBackFunc 	= arguments[5];
					if(arguments.length >= 7)	pJSON.ngmv_MsgFg 	= arguments[6];	
					if(arguments.length >= 8)	pJSON.ngmv_ErrProc 	= arguments[7];		
					if(arguments.length >= 9)	pJSON.encflag		= arguments[8];		
					if(arguments.length >= 10)	pJSON.inPutStr		= arguments[9];
					if(arguments.length >= 11)	pJSON.outPutStr		= arguments[10];

					locFectchBtnObj.setDisabled(false);
					totFectchBtnObj.setDisabled(false);

					var thisObj			= ngmf.scwin.object(this.id);
					var properties 		= thisObj.options;
					var adjustGrdId 	= properties.adjustGrdId;
					var totalDsId 		= properties.totalDsId;
					var totalDs 		= ngmf.scwin.object(totalDsId);
					var splitArr		= pJSON.screenName;
					var adjustGrd		= ngmf.scwin.object(adjustGrdId);
					var adjustGrdDs		= ngmf.scwin.object(adjustGrd.getDataList());

					adjustGrdDs.removeAll();
					totalDs.removeAll();
					var syncType = "asynchronous";

					properties.orgTrxCode = pJSON.orgTrxCode;
					scwin.transaction(syncType, thisObj.id, pJSON, arguments[5]);

				};

				udc_obj.syncCall = function(){

					var pJSON = {};

					if(arguments.length >= 1){
						pJSON.orgTrxCode 	= arguments[0];		
						pJSON.trxCode 		= arguments[0];				
					}

					if(arguments.length >= 2)	pJSON.screenName 	= arguments[1];	
					if(arguments.length >= 3)	pJSON.arg 			= arguments[2];	
					if(arguments.length >= 4)	pJSON.inData 		= arguments[3];	
					if(arguments.length >= 5)	pJSON.outData 		= arguments[4];
					//if(arguments.length >= 6)	pJSON.callBackFunc 	= arguments[5];
					if(arguments.length >= 7)	pJSON.ngmv_MsgFg 	= arguments[6];	
					if(arguments.length >= 8)	pJSON.ngmv_ErrProc 	= arguments[7];		
					if(arguments.length >= 9)	pJSON.encflag		= arguments[8];		
					if(arguments.length >= 10)	pJSON.inPutStr		= arguments[9];
					if(arguments.length >= 11)	pJSON.outPutStr		= arguments[10];

					locFectchBtnObj.setDisabled(false);
					totFectchBtnObj.setDisabled(false);

					var thisObj			= ngmf.scwin.object(this.id);
					var properties 		= thisObj.options;
					var adjustGrdId 	= properties.adjustGrdId;
					var totalDsId 		= properties.totalDsId;
					var totalDs 		= ngmf.scwin.object(totalDsId);
					var splitArr		= pJSON.screenName;
					var adjustGrd		= ngmf.scwin.object(adjustGrdId);
					var adjustGrdDs		= ngmf.scwin.object(adjustGrd.getDataList());

					adjustGrdDs.removeAll();
					totalDs.removeAll();
					var syncType = "synchronous";

					properties.orgTrxCode = pJSON.orgTrxCode;
					scwin.transaction(syncType, thisObj.id, pJSON, arguments[5]);

				};

				scwin.transaction = function(pSyncType, runTimeId, pJSON, pCallbackFunc, resolve){

					var thisObj 		= ngmf.scwin.object(runTimeId);
					var properties 		= thisObj.options;
					var adjustGrdId 	= properties.adjustGrdId;
					var adjustedGrd		= ngmf.scwin.object(adjustGrdId);
					var totalDsId 		= properties.totalDsId;
					var fetchType 		= properties.fetchType;
					var formPageColNm 	= properties.formPageColNm;
					var toPageColNm 	= properties.toPageColNm;
					var recCntColNm 	= properties.recCntColNm;
					var totalDsColNm 	= properties.totalDsColNm;
					var condChkFunc		= properties.conditionCheckFunction;

					// function object이면 String으로 변환
					if (ngmf.isFunction(pCallbackFunc)) {
						pCallbackFunc = ngmf._pushCallbackFunc(pCallbackFunc);
					}

					if(GLV.G_CLOSEFG == "6"){
						return;
					}

					ngmf.bizTrSettingStop(pJSON.trxCode);

					var splitArr		= pJSON.screenName.split("::");
					var inParam  		= pJSON.inData.split(",");
					var outParam 		= pJSON.outData.split(",");
					var inCnt    		= inParam.length;
					var outCnt   		= outParam.length;

					if(splitArr.length > 1){

						if(adjustGrdId.indexOf(splitArr[1]+"_") < 0){
							adjustGrdId = splitArr[1]+"_"+adjustGrdId;
						}

						if(totalDsId.indexOf(splitArr[1]+"_") < 0){
							totalDsId = splitArr[1]+"_"+totalDsId;
						}

						adjustedGrd		= ngmf.scwin.object(adjustGrdId);
						pJSON.screenName = ngmf.apmScreenName(splitArr[0]);

						if(pCallbackFunc.indexOf(splitArr[1]+"_") < 0){
							pCallbackFunc = splitArr[1]+"_"+ngmf.trim(pCallbackFunc);
						}

						for(var i=0; i<inCnt; i++){
							inParam[i] =  splitArr[1]+"_"+ngmf.trim(inParam[i]);
						}

						for(var i=0; i<outCnt; i++){
							outParam[i] =  splitArr[1]+"_"+ngmf.trim(outParam[i]);
						}

					}else{
						pJSON.screenName = ngmf.apmScreenName(pJSON.screenName);
					}

					var adjustedGrdDs	= ngmf.scwin.object(adjustGrdId);
					var strSSO 			= "commonsvc=0";
					var strNewDs		= "";
					var strErrDsList 	= "";
					var errProc 		= pJSON.ngmv_ErrProc 	|| "";
					var encflag 		= pJSON.encflag 		|| false;
					var inPutStr 		= pJSON.inPutStr 		|| "";
					var outPutStr 		= pJSON.outPutStr 		|| "";

					//ref 만들기
					var reqTempArr = new Array();

					for(var i=0; i<inCnt; i++) {
						var pId 	= ngmf.trim(inParam[i]);
						var pKey 	= "input" + (i+1);//ngmf.lpad(""+(i+1),"0",2);

						if(String(properties.wfmID).length > 0){
							if(pId.indexOf(String(properties.wfmID)+"_") < 0){
								pId = String(properties.wfmID)+"_"+pId;
							}
						}

						reqTempArr.push("{'id':'"+pId+"', 'key':'"+pKey+"'}");

						/******************DataList 존재여부 체크********************/

						if (typeof ngmf.scwin.object(pId) === "undefined") {
							ngmf.alert(pId + " 가 존재하지 않습니다.(transaction)");
							return false;
						}

						/******************DataList 존재여부 체크********************/

						var reqDs = WebSquare.wUnit.getObjById( pId );

						if(reqDs.getColumnIndex( "formPageColNm" ) < 0){

							reqDs = null;

							if(reqDs.getColumnIndex( "toPageColNm" ) < 0){

								reqDs = null;

								if(reqDs.getColumnIndex( "recCntColNm" ) < 0){
									reqDs = null;
								}
							}
						}

						properties.reqDs = pId;

						//Error인 경우에도 Data받을 건지에 대한 처리
						if(errProc.toUpperCase() == "ERR_RCV") {
							var upperInparam = ngmf.trim(inParam[i].toUpperCase().replace(":U",""));
							strNewDs = "NGMMIPLAT_" + upperInparam;

							var options = {
							 		id : 		strNewDs,
							 		type : 		"dataList",
							 		option : 	{
							 						"baseNode":			"list", 
							 						"repeatNode":		"map", 
							 						"saveRemovedData":	"true"
							 					},
							 		columnInfo : []
							};

							create(options);
							ngmf.assign(scwin.object(strNewDs), scwin.object(upperInparam));

							if(i==0){
								strErrDsList = strNewDs;
							}else{
								strErrDsList += "," + strNewDs;
							}
						}

						if ( pJSON.encflag) {
							if ( inPutStr.indexOf(inParam[i]) >= 0 ) {
								var tempStr = "input" +(i+1);//+ngmf.lpad((i+1),"0",2);
								inPutStr = inPutStr.replace(inParam[i],tempStr);
							}
						}			
					}

					//target 만들기
					var resTempArr = new Array();
					for(var i=0; i<outCnt; i++)	{
						var pId 	= ngmf.trim(outParam[i]);

						if(String(properties.wfmID).length > 0){
							if(pId.indexOf(String(properties.wfmID)+"_") < 0){
								pId = String(properties.wfmID)+"_"+pId;
							}
						}

						/******************DataList 존재여부 체크********************/

						if (typeof ngmf.scwin.object(pId) === "undefined") {
							ngmf.alert(pId + " 가 존재하지 않습니다.(transaction)");
							return false;
						}

						/******************DataList 존재여부 체크********************/

						var pKey 	= "output"+(i+1);
						resTempArr.push('{"id":"'+pId+'", "key":"'+pKey+'"}');
					}

					if(ngmf.makeHeadSet(pJSON.trxCode,pJSON.screenName) != "OK") {

						if(GLV.G_FORMUSEFG == "M") {
							ngmf.setSystemMsg("헤더 정보를 로드하는데 실패 하였습니다.");
						}

						return;     
					}

					var strFg = null;

					if(errProc.toUpperCase() == "ERR_RCV") {
						strFg = 1;
					} else {
						strFg = 0;
					}

					var strUrl = null;

					if ( pJSON.encflag ) {
						strUrl = "ENCNGM::EncSVC" + "?" + strSSO + "&rtcode=" + strFg + "&Trx_code=" + pJSON.trxCode + "&ScreenName=" + pJSON.screenName + ngmv.fCloseAccount;
					} else {
						strUrl = ngmf.SVC_PATH+"/SVC" + "?" + strSSO + "&rtcode=" + strFg + "&Trx_code=" + pJSON.trxCode + "&ScreenName=" + pJSON.screenName + ngmv.fCloseAccount;
					}	

					if(ngmf.length(pJSON.ngmv_MsgFg) == 0){
						pJSON.ngmv_MsgFg = "NONE";
					}


					if(String(properties.wfmID).length > 0){
						pCallbackFunc = String(properties.wfmID)+"_"+pCallbackFunc;
					}

					pJSON.trxCode = ngmf.trim(pJSON.trxCode) + "|" + ngmf.trim(pCallbackFunc) + "|" + ngmf.trim(pJSON.ngmv_MsgFg);

					if(errProc.toUpperCase() == "ERR_RCV" && ngmf.length(strErrDsList) > 0) {
						pJSON.trxCode += "|" + strErrDsList;
					} else {
						pJSON.trxCode += "|";
					}

					if(pJSON.ngmv_MsgFg.toUpperCase() != "SELF") {
						ngmf.setSystemMsg("");
					}		

					var sDate 		= ngmf.extGetHDTime(); //ExtGetHDTime() ==> 웹스퀘어에서는 현재 구현불가
					var	startTime 	= ngmf.timeM();
					startTime 		= ngmf.trim(startTime);
					strUrl 			= ngmf.preTrxCall(strUrl);
					var nIdx 		= GLV.G_iTrxCurIdx;

					pJSON.trxCode += "|" + nIdx;
					pJSON.trxCode += "|" + sDate + "&" + pJSON.screenName + "&" + startTime;
					pJSON.trxCode += "|" + pJSON.inData;

					if ( pJSON.encflag ) {
						strUrl += "&inputEncGbn=" + inPutStr;
						strUrl += "&outputEncGbn=" + inPutStr;
					}

					if($w.getSubmission( pJSON.orgTrxCode ) != null){
						$w.deleteSubmission(pJSON.orgTrxCode);
					}

					strUrl += "&"+pJSON.arg;

					/************************* 통신하기 시작 *************************/
					//서브미션오브젝트 options
					var submissionObj = {
						"id" : 			pJSON.orgTrxCode,
						"ref" : 		"data:json, ["+reqTempArr.join(',')+"]",
						"target" : 		"",
						"action" : 		strUrl,
						"method" : 		"post",
						"mediatype" : 	"application/json",
						"encoding" : 	"UTF-8",
						"instance" : 	"",
						"replace" : 	"",
						"mode" : 		pSyncType,
						"processMsg" : 	"작업을 처리중입니다.",
						"submitDoneHandler" : function(e) {

							var currTotCnt 		= adjustedGrdDs.getRowCount();
							var result 	 		= e.responseJSON;
							var params			= result.params;
							var errorCd			= new Array(); //result.params.ErrorCode;
							var errorMsg 		= new Array(); //result.params.ErrorMsg;

							for(var i=0; i<params.length; i++){
								var errorJSON = params[i];
								var cd = errorJSON.ErrorCode;
								var msg = errorJSON.ErrorMsg;

								errorCd.push(cd);
								errorMsg.push(msg);

								if(msg.indexOf("^^rs^^") > -1){
									var msgArr = msg.split("^^rs^^");
									if(cd != msgArr[1]){
										errorCd.push(msgArr[1]);
									}	
								}
							}

							if(Number(errorCd[0]) == 0){
								for(var i=0; i<resTempArr.length; i++){

									var resTemp = JSON.parse(resTempArr[i]);
									var ds	= WebSquare.wUnit.getObjById( resTemp.id );

									var key = resTemp.key;
									var resultJSON = eval("result."+key);
									var iniRowPosition = ds.getRowPosition();
									if(resultJSON == undefined || resultJSON == "undefined" || resultJSON == null || resultJSON == ""){
										ds.setJSON([], true);
										ds.reform();
										continue;
									}

									//동적으로 컬럼을 만들어준다.
									if(resultJSON.length > 0){

										$.each(resultJSON[0], function(mapKey, mapValue, mapIdx){
											ngmf.insertColumn(ds, mapKey, {
												name: mapKey,
												dataType: "text"
											});
										});

										ds.setJSON(resultJSON, true);
                                        ds.setRowPosition(iniRowPosition);
										adjustedGrd.setTopRowIndex( currTotCnt, true );
										adjustedGrd.setFocusedCell( adjustedGrd.getDisplayRowIndex(currTotCnt) , 0 , false );

									}else{
										ds.setJSON([], true);
										ds.reform();
									}
								}
							}else{
								for(var i=0; i<resTempArr.length; i++){
									var resTemp = JSON.parse(resTempArr[i]);
									var ds	= WebSquare.wUnit.getObjById( resTemp.id );
									ds.setJSON([], true);
									ds.reform();
								}
							}

							ngmv.errorCode 	= errorCd;
							ngmv.errorMsg 	= errorMsg;

		//console.log("pCallbackFunc   " + pCallbackFunc );
							if(pSyncType == "synchronous"){
								ngmf.getArrayTranErrorMsg(
									ngmv.errorCode, ngmv.errorMsg, pJSON.ngmv_MsgFg, strErrDsList, nIdx,
									pJSON.orgTrxCode, sDate, pJSON.screenName, startTime, 0,
									eval("GLV.__smElapsedTime"+nIdx), eval("GLV.__smGlobalId"+nIdx), pJSON.inData, "SYNC", pCallbackFunc
								);
							}else if(pSyncType == "asynchronous"){
								ngmf.result(pJSON.trxCode, ngmv.errorCode, ngmv.errorMsg);
							}

							$w.deleteSubmission(pJSON.orgTrxCod);

							try {
								if( resolve ) {
									//console.log("resolved....");
									resolve({"svcId" : pJSON.orgTrxCode, "errorCode" : ngmv.errorCode, "errorMsg" : ngmv.errorMsg});
									resolve = undefined;
								}
							} catch(eee) {}

						}, // [end] "submitDoneHandler"
						"submitErrorHandler" : function(e) {

							ngmf.errorHandlingMsg(e);

						} // [end] "submitErrorHandler"
					};

					$w.createSubmission( submissionObj );
					$w.executeSubmission(pJSON.orgTrxCode);  //서브미션 실행

					/************************* 통신하기 종료 *************************/
				};

				scwin.setType = function(type){
					if(type == "type01"){
                        locFectchIptObj.setStyle( "display" , "block" );
                        totFectchIptObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle( "display" , "block" );
                        totFectchBtnObj.setStyle( "display" , "block" ); 
                        txt_gbn.setStyle( "display" , "block" );    
                    }else if(type == "type02"){
                        locFectchIptObj.setStyle( "display" , "block" );
                        totFectchIptObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle("margin", 0);
                        txt_gbn.setStyle( "display" , "block" ); 
                    }else if(type == "type03"){
                        locFectchIptObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle( "display" , "block" );
                        totFectchBtnObj.setStyle( "display" , "block" ); 
                        txt_gbn.setStyle( "display" , "none" );     
                    }else if(type == "type04"){
                        locFectchIptObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle( "display" , "block" );
                        locFectchBtnObj.setStyle("margin", 0);  
                        txt_gbn.setStyle( "display" , "none" ); 
                    }
				};

				udc_obj.initPaging(options);
